{
  "name": "树莓派 GPIO 引脚",
  "name_en": "Raspberry Pi GPIO Pins",
  "manufacturer": "Raspberry Pi",
  "description": "这是树莓派单板计算机上的通用输入输出引脚接口，可用于数字输入、数字输出和边沿检测。实验中常用来连接 LED、按键、继电器以及简单传感器，实现设备开关控制、状态采集和基础自动化联动。",
  "description_en": "These are the general-purpose input/output pins on a Raspberry Pi single-board computer, used for digital input, digital output, and edge detection. In laboratory setups they are commonly used to connect LEDs, buttons, relays, and simple sensors for switch control, state sensing, and basic automation tasks.",
  "tag_hints": [
    "Raspberry Pi",
    "GPIO",
    "digital I/O",
    "edge detection",
    "single-board computer",
    "sensor interfacing",
    "lab automation"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭该 GPIO 引脚连接并释放相关资源",
      "description_en": "Close the GPIO pin connection and release associated resources"
    },
    {
      "action_name": "auto-gpio_base",
      "description": "获取 GPIO 基础标识或基地址信息",
      "description_en": "Get the GPIO base identifier or base address information"
    },
    {
      "action_name": "auto-path",
      "description": "获取该 GPIO 引脚对应的系统路径",
      "description_en": "Get the system path corresponding to the GPIO pin"
    },
    {
      "action_name": "auto-path_value",
      "description": "获取该 GPIO 引脚数值节点的系统路径",
      "description_en": "Get the system path of the GPIO pin value node"
    },
    {
      "action_name": "auto-path_dir",
      "description": "获取该 GPIO 引脚方向节点的系统路径",
      "description_en": "Get the system path of the GPIO pin direction node"
    },
    {
      "action_name": "auto-path_edge",
      "description": "获取该 GPIO 引脚边沿检测节点的系统路径",
      "description_en": "Get the system path of the GPIO pin edge-detection node"
    },
    {
      "action_name": "auto-exported",
      "description": "获取该 GPIO 引脚是否已导出",
      "description_en": "Get whether the GPIO pin is exported"
    },
    {
      "action_name": "auto-export",
      "description": "导出该 GPIO 引脚以供系统访问",
      "description_en": "Export the GPIO pin for system access"
    },
    {
      "action_name": "auto-unexport",
      "description": "取消导出该 GPIO 引脚",
      "description_en": "Unexport the GPIO pin"
    },
    {
      "action_name": "auto-watch",
      "description": "开始监视该 GPIO 引脚的状态变化或边沿事件",
      "description_en": "Start watching the GPIO pin for state changes or edge events"
    },
    {
      "action_name": "auto-unwatch",
      "description": "停止监视该 GPIO 引脚的状态变化或边沿事件",
      "description_en": "Stop watching the GPIO pin for state changes or edge events"
    }
  ]
}

